export const THREAD_DEFAULT=Object.freeze({width:3,mode:'outline'});
export function validateThreadAppearance(a){if(a===undefined)return;if(!a||!['thread-appearance-v1','thread-appearance-v2'].includes(a.version)||Object.keys(a).sort().join(',')!=='families,version'||!a.families||Array.isArray(a.families)||Object.keys(a.families).length>8)throw Error('Invalid thread appearance.');for(const [name,v] of Object.entries(a.families)){if(!/^[A-H]$|^foundation$/.test(name)||!v||Object.keys(v).sort().join(',')!==(a.version==='thread-appearance-v2'?'edgeWidth,mode,rank,width':'mode,width')||!['solid','outline'].includes(v.mode)||!Number.isFinite(v.width)||v.width<.5||v.width>30)throw Error('Invalid thread appearance settings.');if(a.version==='thread-appearance-v2'&&(!Number.isInteger(v.rank)||v.rank<1||v.rank>8||!Number.isFinite(v.edgeWidth)||v.edgeWidth<.1||v.edgeWidth>3))throw Error('Invalid family hierarchy or outline weight.');}}
export function threadStyle(a,family){validateThreadAppearance(a);return {...THREAD_DEFAULT,...a?.families[family],mode:'outline'};}
export function threadOpacity(style){return 1-((style.rank||1)-1)*.1;}
export function changeThreadAppearance(a,names,selected,linked,patch){validateThreadAppearance(a);if(!names.includes(selected))throw Error('Select an available thread family.');const result=structuredClone(a||{version:'thread-appearance-v1',families:{}}),extended=result.version==='thread-appearance-v2'||Object.hasOwn(patch,'rank')||Object.hasOwn(patch,'edgeWidth');if(extended){result.version='thread-appearance-v2';for(const name of Object.keys(result.families))result.families[name]={rank:1,edgeWidth:1,...result.families[name]};}for(const name of linked?names:[selected])result.families[name]={...(extended?{rank:1,edgeWidth:1}:{}),...threadStyle(a,name),...patch};validateThreadAppearance(result);return result;}
// Presentation-only miter/bevel ribbon boundary; never feeds certified geometry.
export function outlinePoints(input,width){const p=input.filter((v,i)=>!i||v.x!==input[i-1].x||v.y!==input[i-1].y);if(p.length<2)return [];const r=width/2,n=p.slice(1).map((b,i)=>{const a=p[i],l=Math.hypot(b.x-a.x,b.y-a.y);return{x:-(b.y-a.y)/l,y:(b.x-a.x)/l}});const side=sign=>p.flatMap((v,i)=>{const a=n[Math.max(0,i-1)],b=n[Math.min(n.length-1,i)],den=1+a.x*b.x+a.y*b.y;if(den>=.5)return[{x:v.x+sign*r*(a.x+b.x)/den,y:v.y+sign*r*(a.y+b.y)/den}];return[{x:v.x+sign*r*a.x,y:v.y+sign*r*a.y},{x:v.x+sign*r*b.x,y:v.y+sign*r*b.y}];});return [...side(1),...side(-1).reverse()];}
export function threadPaths(strands,appearance,transform=p=>p){const groups=new Map();for(const s of strands){const family=s.family||s.identity?.roleId,style=threadStyle(appearance,family);if(!groups.has(family))groups.set(family,{family,...style,d:'',fragments:0,segments:0});const out=groups.get(family);for(const f of s.fragments){const points=f.points||[f.start,f.end];if(points.length<2)continue;const draw=style.mode==='outline'?outlinePoints(points,style.width):points;out.d+=(out.d?' ':'')+draw.map((v,i)=>{const q=transform(v);return(i?'L':'M')+q.x+' '+q.y}).join(' ')+(style.mode==='outline'?' Z':'');out.fragments++;out.segments+=points.length-1;}}return [...groups.values()];}
export function threadStroke(style){return style.mode==='outline'?Math.min(style.edgeWidth??1,style.width/4):style.width;}
